    "Write below. A draft keeps the time you wrote it. Make it an event to pin a date, or a period to draw a line down the days it covers.":
      "Infra scribe. Adumbratio tempus scriptionis servat. Fac eventum ut diem figas, aut periodum ut lineam per dies ducas.",
    "The notes are still here. The filters are hiding them.": "Notae manent. Filtra eas celant.",
    "A sample life, so the colored lines have eras to hold. Your notes stay on this device.":
      "Vita exemplaris, ut lineae coloratae aetates habeant. Notae tuae in hoc instrumento manent.",
    "JSON is a full backup, including the trash and any picture kept on a page. The SQLite graph is rebuilt from these notes whenever it is asked a question. It is not a second copy, and export does not save it. A calendar file is the iCalendar standard: events, dated tasks, and periods.":
      "JSON est plena copia, cum deletis et imaginibus. Graphum SQLite ex his notis reficitur cum interrogatur. Non est altera copia, neque exportatio id servat. Fasciculus calendarii est norma iCalendar: eventa, negotia datata, periodi.",
    "On the phone, choose a file the system can keep open, including one inside a folder that already syncs, such as Syncthing. On a computer, choose that same file in a Chromium browser. TLNotes reads and writes it on its own, and keeps whichever note is newer. A deletion travels too. The layout stays on this device. A sealed journal is not written there, because the file would undo the seal. Unseal on both devices to sync, then seal again after.":
      "In telephono elige fasciculum quem systema apertum servare potest, etiam in capsa quae iam congruit, ut Syncthing. In computatorio eundem fasciculum in navigatro Chromium elige. TLNotes ipsum legit et scribit, et notiorem notam servat. Deletio quoque transit. Dispositio in hoc instrumento manet. Diarium obsignatum illuc non scribitur. Solve obsignationem in utroque instrumento, deinde rursus obsigna.",
    "A share can open in the editor, or be added the same way as a line typed in the box. A bare address becomes a link. A line in quotation marks becomes a quotation. Anything else is a draft.":
      "Communicatum aut in editore aperitur, aut sicut linea in capsa scripta additur. Nuda inscriptio fit vinculum. Linea inter virgulas fit dictum. Cetera sunt adumbratio.",
    "Removed notes stay here until you restore them or empty the trash.": "Notae deletae hic manent donec eas restituas aut corbem exinanias.",
    "The app uses this language: the settings, the buttons, and these notes. Quotations lead in it when that wording is here. Page names do the same. This device is the default. Lingua Latina is always listed. Other languages appear when a page or a quotation brings them in.":
      "Programma hac lingua utitur: optiones, nexus, et hae notae. Dicta hac lingua praeeunt cum verba adsunt. Nomina paginarum idem faciunt. Hoc instrumentum est praedefinitum. Lingua Latina semper adest. Aliae linguae apparent cum pagina aut dictum eas affert.",
    "Parchment is the room as it starts. The others change the colour and the edges. Art Deco is a cream page under a black bar edged in gold. Classical is stone, and Tea is paper with one red seal. Ledger is a blue book with a red Now. Admiralty is a chart. Chapel is indigo and gold. Fresco is plaster. Pocket, Dungeon, and Tavern are the old game colours. The type does not change with them. Catalog is a drawer of index cards. Blueprint is a drawing. Terminal is a phosphor screen and sets its own type. Broadsheet is a newspaper page. CDE and IRIX share one old window frame. CDE is wheat on a teal desk. IRIX is gray on an indigo desk. Turbo Vision is the old text window: a pale blue desk, a blue page in a thick white frame, a hard shadow, and its own type. Classic Mac is the platinum desk: a pale pinstripe, a menu bar, and white windows with a striped title.":
      "Membrana est cubiculum quo incipit. Cetera colorem et margines mutant. Ars Deco est pagina lactea sub nigra regula auro cincta. Classica est lapis, et Thea charta uno sigillo rubro. Codex est liber caeruleus cum Nunc rubro. Curia navalis est tabula. Sacellum est indicum et aurum. Tectorium est calx. Loculus, Crypta, et Caupona sunt colores ludorum veterum. Litterae cum eis non mutantur. Catalogus est capsa chartarum. Ichnographia est forma. Terminale est lumen phosphori et suas litteras ponit. Acta sunt pagina diurna. CDE et IRIX unum vetus limen fenestrae habent. CDE est triticum in mensa viridi. IRIX est cinis in mensa indica. Turbo Vision est fenestra litterarum vetus: mensa caesialis, pagina caerulea in limite albo crasso, umbra dura, et suae litterae. Mac Vetus est mensa platini: linea tenuis, regula ciborum, et fenestrae albae cum titulo striato.",
    "Five Monaspace faces, kept in the app. Nothing is fetched for the type. Size scales the whole page.":
      "Quinque facies Monaspace in programmate servantur. Nihil pro litteris petitur. Magnitudo totam paginam mutat.",
    "Right-handed puts the scope rail and the buttons on the right, and left-handed puts them on the left. Floating is a vertical stack over the lower tail of the timeline. Strip is a transparent row, so the page stays clear. Scope lines, period rules, and the Now line share the line weight.":
      "Dextera regulam et nexus ad dextram ponit, sinistra ad sinistram. Librata est acervus verticalis super caudam lineae dierum. Series est ordo pellucidus, ut pagina libera maneat. Lineae ambitus, regulae periodorum, et linea Nunc eandem crassitudinem habent.",
    "Notes is everything kept, including pages. Pictures counts images saved in the journal, not an address that still points elsewhere. Size is the whole backup. In pictures is how much of that backup those images take.":
      "Notae sunt omnia servata, etiam paginae. Imagines numerant eas in diario servatas, non inscriptionem quae alio spectat. Magnitudo est tota copia. In imaginibus est quantum imaginum ea copia tenet.",
    "OneLook lists the dictionaries for a word, then the Wiktionary senses. Wiktionary, on its own, uses the app language, English, and Latin. Wikipedia is the lead from that encyclopedia, with a small picture when there is one. EncycloSearch and Oldpedia keep a short entry and name the other encyclopedias that have the subject. Oldpedia can be slow. Wikidata is the entity, and an address of a wiki page keeps a link to the original. The article itself is not copied whole.":
      "OneLook lexica verbi enumerat, deinde sensus Wiktionarii. Wiktionarium solum lingua programmatis, Anglica, et Latina utitur. Vicipaedia est initium illius encyclopaediae, cum parva imagine si adest. EncycloSearch et Oldpedia brevem locum servant et ceteras encyclopaedias nominant. Oldpedia tardum esse potest. Wikidata est res ipsa, et inscriptio paginae wiki vinculum ad originale servat. Commentarius totus non transcribitur.",
    "A life, with the ordinary notes outnumbering the quotations, and a shelf of sayings in the languages they were written in. Both can be removed.":
      "Vita, in qua notae usitatae dicta superant, et pluteus dictorum linguis suis. Utraque tolli possunt.",
    "Optional. A passphrase seals the notes on this device, and a recovery key is shown once. Fingerprint, face, or PIN can be added afterwards. It is never the only way in.":
      "Libera. Tessera notas in hoc instrumento obsignat, et clavis semel ostenditur. Digitus, vultus, aut PIN postea addi possunt. Numquam sola via est.",
    "No meaning model is on. Text search still works.": "Nullum exemplar sensus ardet. Quaestio verborum tamen valet.",
