    "Chromium hides the file picker in a page that is inside another window, or that is not https. Open TLNotes in its own tab and choose the file there.": "Chromium cache le choix de fichier dans une page qui est dans une autre fenêtre, ou qui n'est pas en https. Ouvre TLNotes dans son propre onglet et choisis le fichier là.",
