    "Nothing in this view matches.": "Niente in questa vista corrisponde.",
    "Nothing on the timeline to jump to yet.": "Ancora niente sulla cronologia a cui saltare.",
    "The type filter is leaving them out of this list.": "Il filtro di tipo le lascia fuori da questo elenco.",
    "Drag a task by the bar at its edge. Drop it on another to nest it.": "Trascina un compito dalla barra al suo bordo. Rilascialo su un altro per annidarlo.",
    "Leave the end year empty and the line stays open.": "Lascia vuoto l'anno finale e la linea resta aperta.",
    "The words in their original language are the title of the saying.": "Le parole nella lingua originale sono il titolo del detto.",
    "The notes are still here. The filters are hiding them.": "Le note sono ancora qui. I filtri le nascondono.",
    "Write below. A draft keeps the time you wrote it. Make it an event to pin a date, or a period to draw a line down the days it covers.": "Scrivi sotto. Una bozza tiene l'ora in cui l'hai scritta. Falla un evento per fissare una data, o un periodo per tracciare una linea sui giorni che copre.",
    "A sample life, so the colored lines have eras to hold. Your notes stay on this device.": "Una vita di esempio, così le linee colorate hanno epoche da tenere. Le tue note restano su questo dispositivo.",
    "A search is BM25 over the view that is open. Stem and Fuzzy sit on the search itself. A meaning model is optional, fetched once, and kept in this browser. It is not part of the backup.": "Una ricerca è BM25 sulla vista aperta. Radice e approssimata stanno sulla ricerca stessa. Un modello di senso è facoltativo, recuperato una volta e tenuto in questo browser. Non fa parte della copia.",
    "Multilingual E5 is a smaller model made for search across languages.": "E5 multilingue è un modello più piccolo fatto per cercare tra le lingue.",
    "EmbeddingGemma is a larger multilingual model. The copy used here is reduced so it can stay on the device.": "EmbeddingGemma è un modello multilingue più grande. La copia usata qui è ridotta perché possa restare sul dispositivo.",
    "This browser cannot install TLNotes, and updates are not available here.": "Questo browser non può installare TLNotes, e gli aggiornamenti qui non ci sono.",
    "An update is ready and waits until you apply it. Export from Data first if you want a copy.": "Un aggiornamento è pronto e aspetta che tu lo applichi. Esporta prima da Dati se vuoi una copia.",
    "An update is ready. This copy stays until you apply it. Export from Data first if you want a copy.": "Un aggiornamento è pronto. Questa copia resta finché non lo applichi. Esporta prima da Dati se vuoi una copia.",
    "Checking the published copy.": "Controllo della copia pubblicata.",
    "This check could not see the published copy, so nothing was called current and nothing was applied.": "Questo controllo non ha potuto vedere la copia pubblicata, quindi niente è stato detto attuale e niente è stato applicato.",
    "This is an installed PWA.": "Questa è una PWA installata.",
    "In Safari, use Share, then Add to Home Screen.": "In Safari, usa Condividi, poi Aggiungi a Home.",
    "This copy matches the published one. A newer one will wait until you apply it.": "Questa copia corrisponde a quella pubblicata. Una più nuova aspetterà che tu la applichi.",
    "Check compares this copy with the published one. Nothing changes until you apply an update.": "Il controllo confronta questa copia con quella pubblicata. Niente cambia finché non applichi un aggiornamento.",
    "1 done": "1 fatto",
    "1 note": "1 nota",
    "1 open": "1 aperta",
    "A MyST page. Titles are its names, and links are its relations.": "Una pagina MyST. I titoli sono i nomi, i collegamenti le relazioni.",
    "A book. The title is its name. Authors and subjects are names of other pages.": "Un libro. Il titolo è il nome. Autori e soggetti sono nomi di altre pagine.",
    "A book. The title is its name. Authors, form, and edition are the record.": "Un libro. Il titolo è il nome. Autori, forma ed edizione sono la scheda.",
    "A clip. Words are optional. The length kept is the start, up to twenty seconds.": "Una clip. Le parole sono facoltative. Si tiene l'inizio, fino a venti secondi.",
    "A few words, if you want": "Poche parole, se vuoi",
    "A large picture or clip is shrunk before it is kept. A clip longer than twenty seconds keeps only the start. Fetching keeps the address, and the file when the site allows it.": "Un'immagine o una clip grande viene ridotta prima di restare. Una clip oltre venti secondi tiene solo l'inizio. Il recupero tiene l'indirizzo, e il file se il sito lo consente.",
    "A long phrase is the sort of secret that holds.": "Una frase lunga è il segreto che regge.",
    "A name": "Un nome",
    "A name, or Q42": "Un nome, o Q42",
    "A new tag": "Un'etichetta nuova",
    "A person in the repertorium. Not a timeline note.": "Una persona nel repertorio. Non una nota della linea del tempo.",
    "A person, kept in the repertorium. The title is the name.": "Una persona, tenuta nel repertorio. Il titolo è il nome.",
    "A picture. Words are optional.": "Un'immagine. Le parole sono facoltative.",
    "A property, a value, and only the qualifier and source that change the claim.": "Una proprietà, un valore, e solo il qualificatore e la fonte che cambiano l'affermazione.",
    "A sealed journal is not written to the sync file. Unseal it on both devices to sync, then seal it again.": "Un diario sigillato non si scrive nel file di sincronizzazione. Aprilo su entrambi i dispositivi, poi sigillalo di nuovo.",
    "A small picture address": "Indirizzo di una piccola immagine",
