    "A subject": "Un soggetto",
    "A tap adds or removes a tag. A double-tap or a long press keeps only that one. Order is the arrangement you dragged. Edited and Added sort by those times. Done stays hidden until you show it.": "Un tocco aggiunge o toglie un'etichetta. Un doppio tocco o una pressione lunga lascia solo quella. Ordine è la disposizione che hai trascinato. Modificato e Aggiunto ordinano per quei tempi. Fatti resta nascosto finché non lo mostri.",
    "A tap adds or removes. A double-tap or a long press keeps only that one.": "Un tocco aggiunge o toglie. Un doppio tocco o una pressione lunga lascia solo quello.",
