    "The app uses this language: the settings, the buttons, and these notes. Quotations lead in it when that wording is here. Page names do the same. This device is the default. Lingua Latina is always listed. Other languages appear when a page or a quotation brings them in.":
      "A aplicação usa esta língua: as definições, os botões e estas notas. As citações vão à frente nela quando esse texto está aqui. Os nomes das páginas também. Este aparelho é o valor inicial. Lingua Latina está sempre na lista. Outras línguas aparecem quando uma página ou uma citação as traz.",
