    "Translated by": "Vertaald door",
    "Nothing in this view matches.": "Niets in deze weergave komt overeen.",
    "Nothing on the timeline to jump to yet.": "Nog niets op de tijdlijn om naartoe te springen.",
    "The type filter is leaving them out of this list.": "Het typefilter laat ze uit deze lijst.",
    "Drag a task by the bar at its edge. Drop it on another to nest it.": "Sleep een taak aan de balk aan de rand. Laat hem op een andere vallen om hem te nesten.",
    "Leave the end year empty and the line stays open.": "Laat het eindjaar leeg en de lijn blijft open.",
    "The words in their original language are the title of the saying.": "De woorden in de oorspronkelijke taal zijn de titel van het gezegde.",
    "The notes are still here. The filters are hiding them.": "De notities zijn er nog. De filters verbergen ze.",
    "Write below. A draft keeps the time you wrote it. Make it an event to pin a date, or a period to draw a line down the days it covers.": "Schrijf hieronder. Een klad houdt het tijdstip waarop je het schreef. Maak er een gebeurtenis van om een datum te zetten, of een periode om een lijn te trekken langs de dagen die hij dekt.",
    "A sample life, so the colored lines have eras to hold. Your notes stay on this device.": "Een voorbeeldleven, zodat de gekleurde lijnen tijdperken hebben om vast te houden. Je notities blijven op dit apparaat.",
    "A search is BM25 over the view that is open. Stem and Fuzzy sit on the search itself. A meaning model is optional, fetched once, and kept in this browser. It is not part of the backup.": "Een zoekopdracht is BM25 over de open weergave. Stam en vaag zitten op de zoekopdracht zelf. Een betekenismodel is naar keuze, eenmaal opgehaald en in deze browser bewaard. Het hoort niet bij de reservekopie.",
    "Multilingual E5 is a smaller model made for search across languages.": "Meertalige E5 is een kleiner model gemaakt om over talen te zoeken.",
    "EmbeddingGemma is a larger multilingual model. The copy used here is reduced so it can stay on the device.": "EmbeddingGemma is een groter meertalig model. Het exemplaar dat hier wordt gebruikt is verkleind zodat het op het apparaat kan blijven.",
    "This browser cannot install TLNotes, and updates are not available here.": "Deze browser kan TLNotes niet installeren, en updates zijn hier niet beschikbaar.",
    "An update is ready and waits until you apply it. Export from Data first if you want a copy.": "Een update is klaar en wacht tot je hem toepast. Exporteer eerst uit Gegevens als je een kopie wilt.",
    "An update is ready. This copy stays until you apply it. Export from Data first if you want a copy.": "Een update is klaar. Dit exemplaar blijft tot je hem toepast. Exporteer eerst uit Gegevens als je een kopie wilt.",
    "Checking the published copy.": "De gepubliceerde kopie wordt nagekeken.",
    "This check could not see the published copy, so nothing was called current and nothing was applied.": "Deze controle kon de gepubliceerde kopie niet zien, dus niets werd actueel genoemd en niets werd toegepast.",
    "This is an installed PWA.": "Dit is een geïnstalleerde PWA.",
    "In Safari, use Share, then Add to Home Screen.": "In Safari: Delen, dan Zet op beginscherm.",
    "This copy matches the published one. A newer one will wait until you apply it.": "Dit exemplaar komt overeen met het gepubliceerde. Een nieuwere wacht tot je hem toepast.",
    "Check compares this copy with the published one. Nothing changes until you apply an update.": "De controle vergelijkt dit exemplaar met het gepubliceerde. Er verandert niets tot je een update toepast.",
    "1 done": "1 klaar",
    "1 note": "1 notitie",
    "1 open": "1 open",
    "A MyST page. Titles are its names, and links are its relations.": "Een MyST-pagina. Titels zijn de namen, verwijzingen de relaties.",
    "A book. The title is its name. Authors and subjects are names of other pages.": "Een boek. De titel is de naam. Auteurs en onderwerpen zijn namen van andere pagina's.",
    "A book. The title is its name. Authors, form, and edition are the record.": "Een boek. De titel is de naam. Auteurs, vorm en editie zijn de kaart.",
    "A clip. Words are optional. The length kept is the start, up to twenty seconds.": "Een clip. Woorden zijn vrij. Het begin blijft, tot twintig seconden.",
    "A few words, if you want": "Een paar woorden, als je wilt",
    "A large picture or clip is shrunk before it is kept. A clip longer than twenty seconds keeps only the start. Fetching keeps the address, and the file when the site allows it.": "Een grote afbeelding of clip wordt kleiner voor hij blijft. Een clip langer dan twintig seconden houdt alleen het begin. Ophalen houdt het adres, en het bestand als de site het toelaat.",
    "A long phrase is the sort of secret that holds.": "Een lange zin is het geheim dat houdt.",
    "A name": "Een naam",
    "A name, or Q42": "Een naam, of Q42",
    "A new tag": "Een nieuw label",
    "A person in the repertorium. Not a timeline note.": "Een persoon in het repertorium. Geen notitie van de tijdlijn.",
    "A person, kept in the repertorium. The title is the name.": "Een persoon, in het repertorium. De titel is de naam.",
    "A picture. Words are optional.": "Een afbeelding. Woorden zijn vrij.",
    "A property, a value, and only the qualifier and source that change the claim.": "Een eigenschap, een waarde, en alleen de bepaling en de bron die de bewering veranderen.",
    "A sealed journal is not written to the sync file. Unseal it on both devices to sync, then seal it again.": "Een verzegeld dagboek gaat niet naar het syncbestand. Ontzegel het op beide apparaten, en verzegel het daarna weer.",
    "A small picture address": "Adres van een kleine afbeelding",
    "A span. It draws a line across the timeline.": "Een span. Het trekt een lijn over de tijdlijn.",
    "A subject": "Een onderwerp",
    "A tap adds or removes a tag. A double-tap or a long press keeps only that one. Order is the arrangement you dragged. Edited and Added sort by those times. Done stays hidden until you show it.": "Een tik zet of haalt een label weg. Dubbeltikken of lang drukken houdt alleen die. Volgorde is de rang die je sleepte. Gewijzigd en Toegevoegd sorteren op die tijden. Klaar blijft verborgen tot je het toont.",
    "A tap adds or removes. A double-tap or a long press keeps only that one.": "Een tik zet of haalt weg. Dubbeltikken of lang drukken houdt alleen die.",
