      "Приложение говорит на этом языке: настройки, кнопки и эти пояснения. Цитаты выходят на нём вперёд, когда этот текст есть. Имена страниц тоже. Это устройство — значение по умолчанию. Lingua Latina всегда в списке. Другие языки появляются, когда их приносит страница или цитата.",
