    "A window was blocked. Allow it, or open TLNotes in its own tab and choose the file there.": "Окно было заблокировано. Разреши его или открой TLNotes в своей вкладке и выбери файл там.",
    "A word": "Слово",
    "A word, in the language it was kept.": "Слово, на том языке, на котором оно хранится.",
