    "A MyST page. Titles are its names, and links are its relations.": "MyST のページ。題は名、リンクは関係。",
    "A book. The title is its name. Authors and subjects are names of other pages.": "書物。題がその名。著者と主題はほかのページの名。",
    "A book. The title is its name. Authors, form, and edition are the record.": "書物。題が名。著者、形、版が記録。",
    "A clip. Words are optional. The length kept is the start, up to twenty seconds.": "動画。言葉は任意。残るのは先頭、二十秒まで。",
    "A few words, if you want": "数語、あれば",
    "A large picture or clip is shrunk before it is kept. A clip longer than twenty seconds keeps only the start. Fetching keeps the address, and the file when the site allows it.": "大きな絵や動画は残す前に縮む。二十秒を超える動画は先頭だけ。取得はアドレスを残し、サイトが許せばファイルも。",
