    "Choose the file in the window that just opened. This page can use it once that is done.": "اختر الملف في النافذة التي فُتحت. تستطيع هذه الصفحة استخدامه بعد ذلك.",
    "Chromium hides the file picker in a page that is inside another window, or that is not https. Open TLNotes in its own tab and choose the file there.": "يخفي Chromium منتقي الملفات في صفحة داخل نافذة أخرى، أو ليست https. افتح TLNotes في لسانه واختر الملف هناك.",
