    "The app uses this language: the settings, the buttons, and these notes. Quotations lead in it when that wording is here. Page names do the same. This device is the default. Lingua Latina is always listed. Other languages appear when a page or a quotation brings them in.":
      "Η εφαρμογή χρησιμοποιεί αυτή τη γλώσσα: τις ρυθμίσεις, τα κουμπιά και αυτές τις σημειώσεις. Τα παραθέματα προπορεύονται σε αυτήν όταν υπάρχει εκείνη η διατύπωση. Το ίδιο και τα ονόματα των σελίδων. Αυτή η συσκευή είναι η αρχή. Η Lingua Latina είναι πάντα στον κατάλογο. Άλλες γλώσσες εμφανίζονται όταν τις φέρνει μια σελίδα ή ένα παράθεμα.",
    "Removed notes stay here until you restore them or empty the trash.": "Οι αφαιρεμένες σημειώσεις μένουν εδώ ώσπου να τις επαναφέρεις ή να αδειάσεις τα απορρίμματα.",
    "No meaning model is on. Text search still works.": "Κανένα πρότυπο νοήματος δεν είναι ανοιχτό. Η αναζήτηση κειμένου δουλεύει ακόμη.",
  
