    "Add {n} item from the calendar? Matching notes are updated, not duplicated.": "Προσθήκη {n} στοιχείου από το ημερολόγιο; Οι σημειώσεις που ταιριάζουν ενημερώνονται, δεν διπλασιάζονται.",
